"use client";

import { useMemo, useState } from "react";
import type { BrandConfig, ControlConfig, FieldId, GenerateResult } from "@pxlhut/brand-core";
import { PublishAbortedError, useBrandEditor, type LogoVariant } from "@pxlhut/brand-editor";
import type { DraftPatch, PublishResult } from "@pxlhut/brand-store/service";

import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";

import { FieldControl } from "./field-control";
import { PreviewPane } from "./preview-pane";
import { PublishBar } from "./publish-bar";

export interface BrandEditorProps {
  /** The vendor's live tier authority (§9, §31) — see `useBrandEditor`'s own doc comment on why it's a separate input from `initial.controlConfig`. */
  controlConfig: ControlConfig;
  initial: BrandConfig;
  onSave: (patch: DraftPatch) => Promise<BrandConfig>;
  onPublish: () => Promise<PublishResult>;
  onUploadLogo?: (file: File, variant: LogoVariant) => Promise<string>;
  /** Refetches the site's current config after a conflict (§22). The "Reload latest" button is hidden without it — see `PublishBar`. */
  onReloadRequested?: () => Promise<BrandConfig>;
  /** @default 400 (§3) */
  debounceMs?: number;
  /** @default '[data-site-theme]' (§5) — keep `PreviewPane`'s own container in sync if this changes. */
  previewSelector?: string;
  className?: string;
}

type Violation = GenerateResult["violations"][number];

const SECTIONS: readonly { key: string; label: string; fields: readonly FieldId[] }[] = [
  { key: "identity", label: "Identity", fields: ["companyName", "logo", "supportUrl", "emailSenderName"] },
  { key: "brand", label: "Brand", fields: ["brandColor", "semanticColors"] },
  {
    key: "style",
    label: "Typography & shape",
    fields: ["headingFont", "bodyFont", "radius", "density", "neutralTone", "buttonStyle", "elevation"],
  },
  { key: "advanced", label: "Advanced", fields: ["advancedTokens"] },
];

/**
 * The one exported component (§17's own framing): renders entirely from
 * `controlConfig` via `useBrandEditor` (`@pxlhut/brand-editor`, a real npm
 * dependency, not copied). Everything below is copied source — restyle
 * freely, none of it is guarded by a stable prop contract the way the hook
 * is.
 */
export function BrandEditor({
  controlConfig,
  initial,
  onSave,
  onPublish,
  onUploadLogo,
  onReloadRequested,
  debounceMs,
  previewSelector,
  className,
}: BrandEditorProps) {
  const state = useBrandEditor({
    controlConfig,
    initial,
    onSave,
    onPublish,
    ...(onUploadLogo !== undefined ? { onUploadLogo } : {}),
    ...(debounceMs !== undefined ? { debounceMs } : {}),
    ...(previewSelector !== undefined ? { previewSelector } : {}),
  });

  const [tab, setTab] = useState<string>(SECTIONS[0]!.key);
  const [reloading, setReloading] = useState(false);
  const [publishError, setPublishError] = useState<string | null>(null);

  const violationsByField = useMemo(() => {
    const out: Partial<Record<FieldId, Violation[]>> = {};
    for (const violation of state.preview.violations) {
      const field = state.preview.fieldForViolation(violation);
      out[field] = [...(out[field] ?? []), violation];
    }
    return out;
  }, [state.preview]);

  const dirty = useMemo(() => Object.values(state.fields).some((field) => field.dirty), [state.fields]);

  const handlePublish = () => {
    setPublishError(null);
    state.publish().catch((err: unknown) => {
      // A conflict abort is already surfaced via `state.conflict`; a contrast rejection resolves normally into per-field errors instead of throwing. Anything else reaching here is the consumer's own `onPublish` failing (a network error, a thrown 500) and needs its own visible state — an unhandled rejection is not a publish failure UI.
      if (err instanceof PublishAbortedError) return;
      setPublishError(err instanceof Error ? err.message : String(err));
    });
  };

  const handleReload = onReloadRequested
    ? () => {
        setReloading(true);
        onReloadRequested()
          .then((config) => state.reload(config))
          .finally(() => setReloading(false));
      }
    : undefined;

  return (
    <div className={cn("grid gap-4 lg:grid-cols-[minmax(0,1fr)_320px]", className)}>
      <div className="grid gap-4">
        <PublishBar
          dirty={dirty}
          saving={state.saving}
          saveError={state.saveError}
          publishError={publishError}
          conflict={state.conflict}
          canPublish={state.canPublish}
          publishing={state.publishing}
          onPublish={handlePublish}
          onReloadRequested={reloading ? undefined : handleReload}
        />

        <Tabs value={tab} onValueChange={setTab}>
          <TabsList>
            {SECTIONS.map((section) => (
              <TabsTrigger key={section.key} value={section.key}>
                {section.label}
              </TabsTrigger>
            ))}
          </TabsList>
          {SECTIONS.map((section) => (
            <TabsContent key={section.key} value={section.key} className="grid gap-4">
              {section.fields.map((id) => (
                <FieldControl
                  key={id}
                  state={state.fields[id]}
                  violations={violationsByField[id] ?? []}
                  logo={id === "logo" ? state.logo : undefined}
                />
              ))}
            </TabsContent>
          ))}
        </Tabs>
      </div>

      <PreviewPane
        preview={state.preview}
        companyName={state.fields.companyName.value}
        logoUrl={state.logo.light.url}
        className="lg:sticky lg:top-4 lg:self-start"
      />
    </div>
  );
}

"use client";

import type { ReactNode } from "react";
import type { FieldId, GenerateResult } from "@pxlhut/brand-core";
import type { FieldStates, LogoAssetsState } from "@pxlhut/brand-editor";
import type { SemanticColorRole } from "@pxlhut/brand-store/service";

import { AssetControl } from "./controls/asset-control";
import { ColorControl, SemanticColorsControl } from "./controls/color-control";
import { LockedControl } from "./controls/locked-control";
import { RawControl } from "./controls/raw-control";
import { SelectControl } from "./controls/select-control";
import { SliderControl } from "./controls/slider-control";
import { TextControl } from "./controls/text-control";
import { FIELD_COPY } from "./field-copy";
import { FieldRow } from "./field-row";

type Violation = GenerateResult["violations"][number];

export interface FieldControlProps {
  /**
   * `FieldStates[FieldId]` rather than `FieldState<FieldId>` — indexing the
   * mapped `FieldStates` type with the full `FieldId` union produces a union
   * of each field's own narrowly-typed `FieldState<K>`, which is what
   * `state.fields[id]` actually is at the call site. `FieldState<FieldId>`
   * (the generic instantiated directly with the wide union) looks similar
   * but isn't the same type: its `setValue` would accept *any* field's
   * value, which no real per-field `setValue` does.
   */
  state: FieldStates[FieldId];
  /** Pre-filtered to this field by `preview.fieldForViolation` — only `brandColor` and `semanticColors` ever get any (§34: everything else is either not a colour or locked). */
  violations: readonly Violation[];
  /** `undefined` for every field but `logo` itself, and for `logo` when `onUploadLogo` wasn't passed to `useBrandEditor` — see `AssetControl`'s own fallback. */
  logo: LogoAssetsState | undefined;
}

function assertNever(value: never): never {
  throw new Error(`unreachable field-control branch: ${JSON.stringify(value)}`);
}

/**
 * The switch step 16's own doc comment describes: `control` is `FieldConfig`
 * (step 03's discriminated union), so `{ tier: 'guided', type: 'select' }`
 * and `{ tier: 'guided', type: 'slider' }` are different renders (§31), and
 * every `DirectValueType` gets its own control. `assertNever` turns a
 * forgotten branch into a compile error instead of a silent blank field.
 */
function renderControl(state: FieldStates[FieldId], violations: readonly Violation[], logo: LogoAssetsState | undefined): ReactNode {
  const { id, control, value, setValue, error } = state;
  const description = FIELD_COPY[id].description;

  switch (control.tier) {
    case "locked":
      return <LockedControl id={id} value={typeof value === "string" ? value : undefined} />;

    case "guided":
      if (control.type === "select") {
        return (
          <SelectControl
            id={id}
            value={value as string}
            setValue={setValue as (next: string) => void}
            options={control.options}
            error={error}
            description={description}
          />
        );
      }
      if (control.type === "slider") {
        return (
          <SliderControl
            id={id}
            value={value as string}
            setValue={setValue as (next: string) => void}
            min={control.min}
            max={control.max}
            step={control.step}
            error={error}
            description={description}
          />
        );
      }
      return assertNever(control);

    case "direct":
      switch (control.type) {
        case "color":
          return id === "semanticColors" ? (
            <SemanticColorsControl
              id={id}
              value={value as Partial<Record<SemanticColorRole, string>>}
              setValue={setValue as (next: Partial<Record<SemanticColorRole, string>>) => void}
              violations={violations}
              error={error}
              description={description}
            />
          ) : (
            <ColorControl
              id={id}
              value={value as string}
              setValue={setValue as (next: string) => void}
              violations={violations}
              error={error}
              description={description}
            />
          );

        case "text":
          return (
            <TextControl id={id} value={value as string} setValue={setValue as (next: string) => void} error={error} description={description} />
          );

        case "length":
          return (
            <TextControl
              id={id}
              value={value as string}
              setValue={setValue as (next: string) => void}
              error={error}
              description={description}
              placeholder="0.5rem"
            />
          );

        case "number":
          return (
            <TextControl
              id={id}
              type="number"
              inputMode="numeric"
              value={value as string}
              setValue={setValue as (next: string) => void}
              error={error}
              description={description}
            />
          );

        case "asset":
          return logo === undefined ? (
            <p className="text-xs text-muted-foreground">Pass `onUploadLogo` to `useBrandEditor` to enable uploads.</p>
          ) : (
            <AssetControl id={id} light={logo.light} dark={logo.dark} error={error} description={description} />
          );

        default:
          return assertNever(control);
      }

    case "raw":
      return (
        <RawControl
          id={id}
          value={value as Record<string, string>}
          setValue={setValue as (next: Record<string, string>) => void}
          violations={violations}
          error={error}
          description={description}
        />
      );

    default:
      return assertNever(control);
  }
}

export function FieldControl({ state, violations, logo }: FieldControlProps) {
  const copy = FIELD_COPY[state.id];
  return (
    <FieldRow id={state.id} label={copy.label} description={copy.description} error={state.error} dirty={state.dirty}>
      {renderControl(state, violations, logo)}
    </FieldRow>
  );
}

import type { FieldId } from "@pxlhut/brand-core";

export interface FieldCopy {
  label: string;
  description?: string;
}

/**
 * Owner-facing label and help text for each §33 field. Deliberately separate
 * from `FIELD_REGISTRY`'s `why` strings in `@pxlhut/brand-core` — those are
 * the developer-facing rationale for a tier choice, not copy for the person
 * filling in the form.
 */
export const FIELD_COPY: Record<FieldId, FieldCopy> = {
  companyName: { label: "Company name" },
  logo: { label: "Logo", description: "Used on both light and dark backgrounds — upload both." },
  brandColor: { label: "Brand colour", description: "The one colour everything else is generated from." },
  semanticColors: { label: "Status colours", description: "Error, success, warning and info." },
  headingFont: { label: "Heading font" },
  bodyFont: { label: "Body font" },
  radius: { label: "Corner style" },
  density: { label: "Density" },
  neutralTone: { label: "Neutral tone" },
  buttonStyle: { label: "Button style" },
  elevation: { label: "Elevation", description: "Surface depth and border strength." },
  advancedTokens: { label: "Advanced tokens", description: "Direct CSS variable overrides. Unguarded." },
  supportUrl: { label: "Support URL" },
  emailSenderName: { label: "Email sender name", description: "The \"From\" name on transactional email." },
};

"use client";

import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

export interface FieldRowProps {
  id: string;
  label: string;
  /** Always passed (possibly `undefined`) from `FieldControl` — a required key of a union type, not an omittable one, so `exactOptionalPropertyTypes` doesn't reject the call site. */
  description: string | undefined;
  error: string | null;
  dirty: boolean;
  children: ReactNode;
  className?: string;
}

/** The ids a control's own `aria-describedby` should list — computed once here so every control agrees on the scheme. */
export function fieldDescribedBy(id: string, opts: { description: string | undefined; error: string | null }): string | undefined {
  const descriptionId = opts.description ? `${id}-description` : undefined;
  const errorId = opts.error ? `${id}-error` : undefined;
  return [descriptionId, errorId].filter(Boolean).join(" ") || undefined;
}

/**
 * `FieldRow`'s group heading id. A single-input control (`TextControl`,
 * `SliderControl`, the `<Select>` branch of `SelectControl`, the lone swatch
 * in `ColorControl`) points its own `aria-labelledby` here — `role="group"`
 * alone only announces the name on entering the group, not on the input
 * itself. Multi-part controls skip this and give each sub-item its own
 * `aria-label` instead (`SemanticColorsControl`, the logo's light/dark pair).
 */
export function fieldHeadingId(id: string): string {
  return `${id}-heading`;
}

/**
 * Label + optional description + control + field-level error, as an ARIA
 * group rather than a `<label htmlFor>` — some controls here are a single
 * input (`htmlFor` would work), others are several (`semanticColors`'
 * four swatches, the logo's light/dark pair), and a group heading is the
 * one relationship that's correct for both. The control itself (passed as
 * `children`) still wires its own `aria-describedby` via `fieldDescribedBy`.
 */
export function FieldRow({ id, label, description, error, dirty, children, className }: FieldRowProps) {
  const headingId = fieldHeadingId(id);
  const descriptionId = description ? `${id}-description` : undefined;
  const errorId = error ? `${id}-error` : undefined;

  return (
    <div role="group" aria-labelledby={headingId} className={cn("grid gap-1.5", className)}>
      <span id={headingId} className="flex items-center gap-1.5 text-sm font-medium leading-none">
        {label}
        {dirty ? (
          <span aria-hidden="true" className="size-1.5 rounded-full bg-primary" title="Unsaved change" />
        ) : null}
      </span>
      {description ? (
        <p id={descriptionId} className="text-xs text-muted-foreground">
          {description}
        </p>
      ) : null}
      {children}
      {error ? (
        <p id={errorId} role="alert" className="text-xs font-medium text-destructive">
          {error}
        </p>
      ) : null}
    </div>
  );
}

"use client";

import type { PreviewResult } from "@pxlhut/brand-editor";

export interface PreviewPaneProps {
  preview: PreviewResult;
  companyName: string;
  logoUrl: string | undefined;
  className?: string;
}

/**
 * §5's one place visual isolation genuinely matters: `preview.css` is
 * already scoped to `[data-site-theme]` (the hook's default `previewSelector`,
 * step 08's `selector` option) so it can sit right next to this dashboard's
 * own chrome without a bare `--primary` leaking onto it. Everything below
 * `<style>` reads its colours from `var(--…)`, never from `preview.tokens`
 * directly — the injected stylesheet is the one source of truth for both.
 *
 * If `useBrandEditor` is given a non-default `previewSelector`, keep this
 * container's own selector in sync — swap the `data-site-theme` attribute
 * below for whatever `previewSelector` resolves to.
 */
export function PreviewPane({ preview, companyName, logoUrl, className }: PreviewPaneProps) {
  return (
    <div className={className}>
      <style>{preview.css}</style>
      <div
        data-site-theme
        style={{
          background: "var(--background)",
          color: "var(--foreground)",
          borderColor: "var(--border)",
        }}
        className="grid gap-4 rounded-[var(--radius)] border p-4"
      >
        <div className="flex items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            {logoUrl ? <img src={logoUrl} alt="" className="h-6 w-auto object-contain" /> : null}
            <span style={{ fontFamily: "var(--font-heading)" }} className="text-sm font-semibold">
              {companyName || "Your company"}
            </span>
          </div>
          <div className="flex gap-2">
            {(["success", "warning", "info", "destructive"] as const).map((role) => (
              <span
                key={role}
                aria-hidden="true"
                title={role}
                className="size-3 rounded-full"
                style={{ background: `var(--${role})` }}
              />
            ))}
          </div>
        </div>

        <p style={{ fontFamily: "var(--font-body)" }} className="text-sm">
          This is body text, set in the body font, on the generated background colour.
        </p>

        <div className="flex flex-wrap items-center gap-2">
          <button
            type="button"
            style={{
              background: "var(--primary)",
              color: "var(--primary-foreground)",
              borderRadius: "var(--radius)",
              borderWidth: "var(--border-width)",
              borderColor: "var(--primary)",
              borderStyle: "solid",
            }}
            className="px-3 py-1.5 text-sm font-medium"
          >
            Primary action
          </button>
          <button
            type="button"
            style={
              // Not a token (§32) — the component library branches on it directly, same as `toShadcnCss`'s own `buttonStyle` option.
              preview.buttonStyle === "outline"
                ? {
                    background: "transparent",
                    color: "var(--primary)",
                    borderRadius: "var(--radius)",
                    borderWidth: "var(--border-width)",
                    borderColor: "var(--primary)",
                    borderStyle: "solid",
                  }
                : {
                    background: "var(--secondary)",
                    color: "var(--secondary-foreground)",
                    borderRadius: "var(--radius)",
                    borderWidth: "var(--border-width)",
                    borderColor: "var(--secondary)",
                    borderStyle: "solid",
                  }
            }
            className="px-3 py-1.5 text-sm font-medium"
          >
            Secondary action
          </button>
          <div
            style={{
              background: "var(--card)",
              color: "var(--card-foreground)",
              borderColor: "var(--border)",
              borderRadius: "var(--radius)",
            }}
            className="border px-3 py-1.5 text-sm"
          >
            Card surface
          </div>
        </div>

        {preview.violations.length > 0 ? (
          <p className="text-xs" style={{ color: "var(--destructive)" }}>
            {preview.violations.length} colour {preview.violations.length === 1 ? "pairing needs" : "pairings need"} more contrast before this can
            publish.
          </p>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

export interface PublishBarProps {
  dirty: boolean;
  saving: boolean;
  saveError: string | null;
  /** An `onPublish` rejection that wasn't a conflict abort or a contrast rejection — e.g. the consumer's own API route threw. Neither of those two other cases reach here: a conflict is `conflict`, and a contrast rejection resolves normally into per-field errors instead of throwing. */
  publishError: string | null;
  conflict: boolean;
  canPublish: boolean;
  publishing: boolean;
  onPublish: () => void;
  /** Wired by the consumer to refetch the site's current config; `undefined` to just show the conflict message with no action (also `undefined` transiently while a reload is already in flight). */
  onReloadRequested: (() => void) | undefined;
}

function statusText(dirty: boolean, saving: boolean, saveError: string | null): string {
  if (saveError) return "Draft save failed";
  if (saving) return "Saving…";
  if (dirty) return "Unsaved changes";
  return "All changes saved";
}

/**
 * Dirty state, `canPublish`, and the conflict signal step 16's own hook
 * makes distinct from a generic error (§22) — a stale `expectedVersion`
 * needs "someone else changed this" messaging, not a toast that reads like
 * this owner's own save failed.
 */
export function PublishBar({
  dirty,
  saving,
  saveError,
  publishError,
  conflict,
  canPublish,
  publishing,
  onPublish,
  onReloadRequested,
}: PublishBarProps) {
  return (
    <div className="grid gap-2">
      <div className="flex items-center justify-between gap-3">
        <p aria-live="polite" className="text-sm text-muted-foreground">
          {statusText(dirty, saving, saveError)}
        </p>
        <Button type="button" onClick={onPublish} disabled={!canPublish || publishing}>
          {publishing ? "Publishing…" : "Publish"}
        </Button>
      </div>

      {conflict ? (
        <Alert variant="destructive">
          <AlertTitle>Someone else changed this</AlertTitle>
          <AlertDescription>
            {onReloadRequested ? (
              <span className="flex items-center justify-between gap-2">
                This draft is out of date.
                <Button type="button" size="sm" variant="outline" onClick={onReloadRequested}>
                  Reload latest
                </Button>
              </span>
            ) : (
              "This draft is out of date. Reload the page to see the latest version."
            )}
          </AlertDescription>
        </Alert>
      ) : null}

      {saveError ? (
        <Alert variant="destructive">
          <AlertDescription>{saveError}</AlertDescription>
        </Alert>
      ) : null}

      {publishError ? (
        <Alert variant="destructive">
          <AlertTitle>Publish failed</AlertTitle>
          <AlertDescription>{publishError}</AlertDescription>
        </Alert>
      ) : null}

      {!canPublish && !conflict ? (
        <p className="text-xs text-muted-foreground">Resolve the contrast issues below before publishing.</p>
      ) : null}
    </div>
  );
}

"use client";

import type { LogoVariant, LogoVariantState } from "@pxlhut/brand-editor";

import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { fieldDescribedBy } from "../field-row";

export interface AssetControlProps {
  id: string;
  light: LogoVariantState;
  dark: LogoVariantState;
  error: string | null;
  description: string | undefined;
}

const VARIANT_META: Record<LogoVariant, { label: string; previewClassName: string }> = {
  light: { label: "Light background", previewClassName: "bg-white" },
  dark: { label: "Dark background", previewClassName: "bg-neutral-900" },
};

function VariantUploader({
  variant,
  variantId,
  state,
  describedBy,
}: {
  variant: LogoVariant;
  variantId: string;
  state: LogoVariantState;
  describedBy: string | undefined;
}) {
  const meta = VARIANT_META[variant];
  return (
    <div className="grid gap-1.5">
      <div className={`flex h-16 items-center justify-center rounded-lg border border-dashed border-input ${meta.previewClassName}`}>
        {state.url ? (
          // Plain `<img>`, not `next/image` — the upload host is consumer-controlled and arbitrary, so a fixed loader config can't be assumed here.
          <img src={state.url} alt={`${meta.label} logo preview`} className="max-h-12 max-w-[80%] object-contain" />
        ) : (
          <span className="text-xs text-muted-foreground">No logo yet</span>
        )}
      </div>
      <Label htmlFor={variantId} className="text-xs font-normal text-muted-foreground">
        {meta.label}
      </Label>
      <Input
        id={variantId}
        type="file"
        accept="image/*"
        disabled={state.uploading}
        aria-describedby={describedBy}
        onChange={(event) => {
          const file = event.target.files?.[0];
          if (file) void state.upload(file);
          event.target.value = "";
        }}
      />
      {state.uploading ? <p className="text-xs text-muted-foreground">Uploading…</p> : null}
      {state.error ? (
        <p role="alert" className="text-xs font-medium text-destructive">
          {state.error}
        </p>
      ) : null}
    </div>
  );
}

/**
 * §36: a dark-mode logo is not optional, so both variants are always shown
 * side by side rather than a single upload plus a later-added "add a dark
 * variant" affordance.
 */
export function AssetControl({ id, light, dark, error, description }: AssetControlProps) {
  const describedBy = fieldDescribedBy(id, { description, error });
  return (
    <div className="grid grid-cols-2 gap-3">
      <VariantUploader variant="light" variantId={`${id}-light`} state={light} describedBy={describedBy} />
      <VariantUploader variant="dark" variantId={`${id}-dark`} state={dark} describedBy={describedBy} />
    </div>
  );
}

"use client";

import type { GenerateResult } from "@pxlhut/brand-core";
import { SEMANTIC_COLOR_ROLES, type SemanticColorRole } from "@pxlhut/brand-store/service";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Input } from "@/components/ui/input";

import { fieldDescribedBy, fieldHeadingId } from "../field-row";

type Violation = GenerateResult["violations"][number];

/**
 * The APCA feedback the owner actually experiences (step 16's own framing):
 * a picker reports a colour won't pass *before* Publish is pressed, not
 * after. `violations` is already the same list a rejected publish would
 * report — this just surfaces it live.
 */
export function ColorViolations({ violations }: { violations: readonly Violation[] }) {
  if (violations.length === 0) return null;
  return (
    <Alert variant="destructive">
      <AlertDescription>
        <ul className="list-disc space-y-0.5 pl-4">
          {violations.map((violation, index) => (
            // Light and dark mode can each independently fail the same `fg`/`bg` pairing, so the pairing alone isn't a unique key.
            <li key={`${violation.fg}-${violation.bg}-${index}`}>
              <code className="text-xs">{violation.fg}</code> on <code className="text-xs">{violation.bg}</code> needs
              contrast Lc {violation.min}, got {violation.got}
            </li>
          ))}
        </ul>
      </AlertDescription>
    </Alert>
  );
}

function ColorSwatchInput({
  id,
  label,
  labelledBy,
  value,
  setValue,
  describedBy,
  invalid,
}: {
  id: string;
  label: string;
  /** When the field has exactly one swatch, name it from `FieldRow`'s own heading instead of a generic `label` string. */
  labelledBy?: string;
  value: string;
  setValue: (value: string) => void;
  describedBy: string | undefined;
  invalid?: boolean;
}) {
  return (
    <div className="flex items-center gap-2">
      <input
        type="color"
        aria-label={`${label} swatch`}
        value={/^#[0-9a-fA-F]{6}$/.test(value) ? value : "#000000"}
        onChange={(event) => setValue(event.target.value)}
        className="size-8 shrink-0 cursor-pointer rounded-md border border-input bg-transparent p-0.5"
      />
      <Input
        id={id}
        value={value}
        onChange={(event) => setValue(event.target.value)}
        placeholder="#7c6cff"
        aria-label={labelledBy ? undefined : label}
        aria-labelledby={labelledBy}
        aria-invalid={invalid ? true : undefined}
        aria-describedby={describedBy}
        className="font-mono"
      />
    </div>
  );
}

export interface ColorControlProps {
  id: string;
  value: string;
  setValue: (value: string) => void;
  violations: readonly Violation[];
  error: string | null;
  description: string | undefined;
}

/** `direct: color` on a single-value field (`brandColor`). `semanticColors` uses `SemanticColorsControl` instead — its value is a role map, not one hex string. */
export function ColorControl({ id, value, setValue, violations, error, description }: ColorControlProps) {
  return (
    <div className="grid gap-2">
      <ColorSwatchInput
        id={id}
        label="Colour"
        labelledBy={fieldHeadingId(id)}
        value={value}
        setValue={setValue}
        describedBy={fieldDescribedBy(id, { description, error })}
        invalid={Boolean(error)}
      />
      <ColorViolations violations={violations} />
    </div>
  );
}

const SEMANTIC_LABELS: Record<SemanticColorRole, string> = {
  destructive: "Error",
  success: "Success",
  warning: "Warning",
  info: "Info",
};

export interface SemanticColorsControlProps {
  id: string;
  value: Partial<Record<SemanticColorRole, string>>;
  setValue: (value: Partial<Record<SemanticColorRole, string>>) => void;
  violations: readonly Violation[];
  error: string | null;
  description: string | undefined;
}

/** `semanticColors` at `direct` tier (§34) — four fixed roles, each still a real colour the owner picks and each still APCA-gated. */
export function SemanticColorsControl({ id, value, setValue, violations, error, description }: SemanticColorsControlProps) {
  const describedBy = fieldDescribedBy(id, { description, error });
  return (
    <div className="grid gap-2">
      <div className="grid grid-cols-2 gap-2">
        {SEMANTIC_COLOR_ROLES.map((role) => (
          <ColorSwatchInput
            key={role}
            id={`${id}-${role}`}
            label={SEMANTIC_LABELS[role]}
            value={value[role] ?? ""}
            setValue={(next) => setValue({ ...value, [role]: next })}
            describedBy={describedBy}
            invalid={Boolean(error)}
          />
        ))}
      </div>
      <ColorViolations violations={violations} />
    </div>
  );
}

"use client";

import { LockIcon } from "lucide-react";

export interface LockedControlProps {
  id: string;
  /** `undefined` when the developer didn't pin a display value (§33 — the value is still derived, just not shown as literal text here). */
  value: string | undefined;
}

/**
 * Step 17's own framing: **show it, don't hide it.** An owner seeing
 * "Semantic colours · managed by the platform" understands the product; a
 * missing field looks like a bug. The explanation is real, visible text —
 * not `sr-only` — so it reaches sighted and screen-reader users the same way.
 */
export function LockedControl({ id, value }: LockedControlProps) {
  return (
    <div
      id={id}
      className="flex h-8 items-center justify-between gap-2 rounded-lg border border-input bg-muted/40 px-2.5 text-sm text-muted-foreground"
    >
      <span className="truncate">{value && value.length > 0 ? value : "Set by the platform"}</span>
      <span className="inline-flex shrink-0 items-center gap-1 text-xs">
        <LockIcon aria-hidden="true" className="size-3" />
        Managed by the platform
      </span>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import type { GenerateResult } from "@pxlhut/brand-core";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";

import { fieldDescribedBy, fieldHeadingId } from "../field-row";
import { ColorViolations } from "./color-control";

type Violation = GenerateResult["violations"][number];

export interface RawControlProps {
  id: string;
  value: Record<string, string>;
  setValue: (value: Record<string, string>) => void;
  /** `advancedTokens` and a raw-tier `semanticColors` are both colour paths (§34) — a raw override can fail the same APCA floors a Direct one can. */
  violations: readonly Violation[];
  error: string | null;
  description: string | undefined;
}

function isStringRecord(input: unknown): input is Record<string, string> {
  return (
    typeof input === "object" &&
    input !== null &&
    !Array.isArray(input) &&
    Object.values(input as Record<string, unknown>).every((entry) => typeof entry === "string")
  );
}

/**
 * `raw` tier — "no guardrails beyond the syntax validator" (§33). This is
 * the one control in the registry that doesn't call `setValue` on every
 * keystroke: a half-typed JSON object is invalid JSON on every keystroke but
 * one, so edits apply on "Apply changes" instead, with a parse error shown
 * inline rather than silently discarded.
 */
export function RawControl({ id, value, setValue, violations, error, description }: RawControlProps) {
  const [text, setText] = useState(() => JSON.stringify(value, null, 2));
  const [parseError, setParseError] = useState<string | null>(null);

  // Reflects an external change (e.g. `reload()` after a conflict) without clobbering an in-progress, not-yet-applied edit.
  useEffect(() => setText(JSON.stringify(value, null, 2)), [value]);

  const apply = () => {
    try {
      const parsed: unknown = JSON.parse(text);
      if (!isStringRecord(parsed)) {
        setParseError("Must be a flat JSON object of string values, e.g. { \"color.primary\": \"#123456\" }.");
        return;
      }
      setParseError(null);
      setValue(parsed);
    } catch {
      setParseError("Not valid JSON.");
    }
  };

  return (
    <div className="grid gap-1.5">
      <Badge variant="destructive" className="w-fit">
        Raw · unguarded
      </Badge>
      <Textarea
        id={id}
        value={text}
        onChange={(event) => setText(event.target.value)}
        rows={6}
        spellCheck={false}
        className="font-mono text-xs"
        aria-labelledby={fieldHeadingId(id)}
        aria-invalid={error || parseError ? true : undefined}
        aria-describedby={fieldDescribedBy(id, { description, error: error ?? parseError })}
      />
      <Button type="button" size="sm" variant="outline" className="w-fit" onClick={apply}>
        Apply changes
      </Button>
      {parseError ? (
        <p role="alert" className="text-xs font-medium text-destructive">
          {parseError}
        </p>
      ) : null}
      <ColorViolations violations={violations} />
    </div>
  );
}

"use client";

import type { KeyboardEvent } from "react";
import type { SelectOption } from "@pxlhut/brand-core";

import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

import { fieldDescribedBy, fieldHeadingId } from "../field-row";

export interface SelectControlProps {
  id: string;
  value: string;
  setValue: (value: string) => void;
  options: readonly SelectOption[];
  error: string | null;
  description: string | undefined;
}

/**
 * A plain `role="radiogroup"` of `Button`s rather than shadcn's own
 * `ToggleGroup` — that component's underlying value shape (single value vs.
 * an array) differs across the base libraries shadcn now ships (Base UI,
 * Radix, React Aria), and every consumer's copy of this file has to compile
 * against whichever one their own project uses. `Button` and native
 * `role="radio"` semantics don't have that problem. Arrow keys move the
 * roving tab stop, matching native radio-group behaviour.
 */
function SegmentedControl({
  id,
  value,
  setValue,
  options,
  describedBy,
  labelledBy,
  invalid,
}: {
  id: string;
  value: string;
  setValue: (value: string) => void;
  options: readonly SelectOption[];
  describedBy: string | undefined;
  labelledBy: string;
  invalid: boolean;
}) {
  const move = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== "ArrowRight" && event.key !== "ArrowLeft") return;
    event.preventDefault();
    const index = options.findIndex((option) => option.value === value);
    const delta = event.key === "ArrowRight" ? 1 : -1;
    const next = options[(index + delta + options.length) % options.length];
    if (next) {
      setValue(next.value);
      document.getElementById(`${id}-${next.value}`)?.focus();
    }
  };

  return (
    <div
      id={id}
      role="radiogroup"
      aria-labelledby={labelledBy}
      aria-describedby={describedBy}
      aria-invalid={invalid || undefined}
      onKeyDown={move}
      className="flex flex-wrap gap-1.5"
    >
      {options.map((option) => {
        const selected = option.value === value;
        return (
          <Button
            key={option.value}
            id={`${id}-${option.value}`}
            type="button"
            role="radio"
            aria-checked={selected}
            tabIndex={selected ? 0 : -1}
            variant={selected ? "default" : "outline"}
            size="sm"
            onClick={() => setValue(option.value)}
          >
            {option.label}
          </Button>
        );
      })}
    </div>
  );
}

/**
 * §31's two Guided shapes are different renders, and within `select` there's
 * a second split step 17 owns: a segmented control reads better than a
 * dropdown for a handful of choices, but stops scaling past that — a
 * `<Select>` takes over once there are more than four (matches the
 * Sharp/Soft/Round, Compact/Comfortable, Warm/Cool, Solid/Outline options,
 * all ≤4, while the five curated fonts fall through to `<Select>`).
 */
export function SelectControl({ id, value, setValue, options, error, description }: SelectControlProps) {
  const describedBy = fieldDescribedBy(id, { description, error });

  if (options.length <= 4) {
    return (
      <SegmentedControl
        id={id}
        value={value}
        setValue={setValue}
        options={options}
        describedBy={describedBy}
        labelledBy={fieldHeadingId(id)}
        invalid={Boolean(error)}
      />
    );
  }

  return (
    <Select
      value={value}
      onValueChange={(next) => {
        if (next) setValue(next);
      }}
    >
      <SelectTrigger
        id={id}
        className="w-full"
        aria-labelledby={fieldHeadingId(id)}
        aria-describedby={describedBy}
        aria-invalid={error ? true : undefined}
      >
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {options.map((option) => (
          <SelectItem key={option.value} value={option.value}>
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

"use client";

import { Slider } from "@/components/ui/slider";

import { fieldDescribedBy, fieldHeadingId } from "../field-row";

export interface SliderControlProps {
  id: string;
  /** The hook stores every scalar field as a string (§13's `DraftPatch` shape) — parsed here, formatted back on change. */
  value: string;
  setValue: (value: string) => void;
  min: number;
  max: number;
  step: number | undefined;
  error: string | null;
  description: string | undefined;
}

/** §31's continuous shape — right for elevation, wrong for radius (that's `SelectControl`). */
export function SliderControl({ id, value, setValue, min, max, step, error, description }: SliderControlProps) {
  const numeric = Number(value);
  const current = Number.isFinite(numeric) ? numeric : min;

  return (
    <div className="flex items-center gap-3">
      <Slider
        id={id}
        value={[current]}
        min={min}
        max={max}
        step={step ?? 1}
        onValueChange={(next) => {
          // Some slider implementations report a lone thumb as a plain `number`, others as `number[]` — this control only ever renders one thumb.
          const resolved = Array.isArray(next) ? next[0] : next;
          if (resolved !== undefined) setValue(String(resolved));
        }}
        aria-labelledby={fieldHeadingId(id)}
        aria-describedby={fieldDescribedBy(id, { description, error })}
        aria-invalid={error ? true : undefined}
        className="flex-1"
      />
      <output htmlFor={id} className="w-10 shrink-0 text-right text-sm tabular-nums text-muted-foreground">
        {current}
      </output>
    </div>
  );
}

"use client";

import { Input } from "@/components/ui/input";

import { fieldDescribedBy, fieldHeadingId } from "../field-row";

export interface TextControlProps {
  id: string;
  value: string;
  setValue: (value: string) => void;
  error: string | null;
  description: string | undefined;
  placeholder?: string;
  /** Free text (`direct: text`) vs. a constrained value the owner still types by hand (`direct: length`, `direct: number`). */
  type?: "text" | "url" | "number";
  inputMode?: "text" | "numeric" | "decimal";
}

/** `direct: text`, `direct: length` and `direct: number` all read as a single validated input — the value validator (step 07) is the enforcement boundary, not this control (§9). */
export function TextControl({ id, value, setValue, error, description, placeholder, type = "text", inputMode }: TextControlProps) {
  return (
    <Input
      id={id}
      type={type}
      inputMode={inputMode}
      value={value}
      onChange={(event) => setValue(event.target.value)}
      placeholder={placeholder}
      aria-invalid={error ? true : undefined}
      aria-labelledby={fieldHeadingId(id)}
      aria-describedby={fieldDescribedBy(id, { description, error })}
    />
  );
}
